    void testFindEnclosingAttribute_ReturnsValueFromStartingNode() {
        Namespace ns = Namespace.getNamespace("p", "http://example.org");
        Element child = new Element("child");
        child.setAttribute(new Attribute(ATTR_NAME, "childValue", ns));

        String result = JDOMNodePointer.findEnclosingAttribute(child, ATTR_NAME, ns);
        assertEquals("childValue", result);
