        Element child = new Element("child");
        child.setAttribute(new Attribute(ATTR_NAME, "", ns));

        Element parent = new Element("parent");
        parent.setAttribute(new Attribute(ATTR_NAME, "parentValue", ns));
        parent.addContent(child);

        String result = JDOMNodePointer.findEnclosingAttribute(child, ATTR_NAME, ns);
        assertEquals("parentValue", result);
    }

