        parent.addContent(child);
        grand.addContent(parent);

        grand.setAttribute(new Attribute(ATTR_NAME, "grandValue", ns));

        String result = JDOMNodePointer.findEnclosingAttribute(child, ATTR_NAME, ns);
        assertEquals("grandValue", result);
    }

