package org.apache.commons.jxpath.ri.parser;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class GetSuffixTests {

    private SimpleCharStream createStream(String content, int bufpos) {
        int n = content.length();
        SimpleCharStream s = new SimpleCharStream(new java.io.StringReader(content), 1, 1, n);
        s.buffer = content.toCharArray();
        s.bufsize = n;
        s.bufpos = bufpos;
        return s;
    }

    @Test
    void testGetSuffix_NoWrap() {
        SimpleCharStream s = createStream("abcdef", 5);
        char[] suffix = s.GetSuffix(3);
        assertArrayEquals(new char[]{'d', 'e', 'f'}, suffix);
    }

    @Test
    void testGetSuffix_WrapAround() {
        SimpleCharStream s = createStream("abcdef", 1);
        char[] suffix = s.GetSuffix(3);
        assertArrayEquals(new char[]{'f', 'a', 'b'}, suffix);
    }

    @Test
    void testGetSuffix_FullBuffer() {
        SimpleCharStream s = createStream("abcdef", 3);
        char[] suffix = s.GetSuffix(6);
        assertArrayEquals(new char[]{'e', 'f', 'a', 'b', 'c', 'd'}, suffix);
    }

    @Test
    void testGetSuffix_InvalidLenZero() {
        SimpleCharStream s = createStream("abcdef", 5);
        assertThrows(ArrayIndexOutOfBoundsException.class, () -> s.GetSuffix(0));
    }

    @Test
    void testGetSuffix_LenExceedsBuffer() {
        SimpleCharStream s = createStream("abcdef", 5);
        assertThrows(ArrayIndexOutOfBoundsException.class, () -> s.GetSuffix(7));
    }
}

