import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class Add_escapesTests {

    @Test
    public void testNullInputThrowsNPE() {
        ParseException pe = new ParseException();
        assertThrows(NullPointerException.class, () -> pe.add_escapes(null));
    }

    @Test
    public void testEscapesCommonControlChars() {
        ParseException pe = new ParseException();
        String input = "\b\t\n\r\f\"";
        String escaped = pe.add_escapes(input);
        assertEquals("\\b\\t\\n\\r\\f\\\"", escaped);
    }

    @Test
    public void testEscapesBackslashes() {
        ParseException pe = new ParseException();
        String input = "C:\\folder\\name";
        String escaped = pe.add_escapes(input);
        assertEquals("C:\\\\folder\\\\name", escaped);
    }

    @Test
    public void testEscapesUnicodeCharacters() {
        ParseException pe = new ParseException();
        String input = "caf\u00e9";
        String escaped = pe.add_escapes(input);
        boolean containsUpper = escaped.contains("\\u00E9");
        boolean containsLower = escaped.contains("\\u00e9");
        assertTrue(containsUpper || containsLower, "Output should contain unicode escape for é: " + escaped);
    }

    @Test
    public void testNoEscapeWhenNoSpecialChars() {
        ParseException pe = new ParseException();
        String input = "HelloWorld123";
        String escaped = pe.add_escapes(input);
        assertEquals(input, escaped);
    }

    @Test
    public void testEscapeNewlineAndTabAndCarriageReturn() {
        ParseException pe = new ParseException();
        String input = "\tLine1\nLine2\rEnd";
        String escaped = pe.add_escapes(input);
        String expected = "\\tLine1\\nLine2\\rEnd";
        assertEquals(expected, escaped);
    }
}

