        Document doc = builder.newDocument();

        Element root = doc.createElement("books");
        doc.appendChild(root);

        DOMNodePointer docPtr = new DOMNodePointer(doc, Locale.ENGLISH);
        DOMNodePointer rootPtr = new DOMNodePointer(docPtr, root);

        String path = rootPtr.asPath();
        assertNotNull(path, "Path should not be null for root element");
        assertTrue(path.contains("books"), "Path should include root element name 'books': " + path);
    }

    @Test
    public void testAsPathTextNodeUnderRootContainsParentAndText() throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.newDocument();

        Element root = doc.createElement("books");
        doc.appendChild(root);

        DOMNodePointer docPtr = new DOMNodePointer(doc, Locale.ENGLISH);
        DOMNodePointer rootPtr = new DOMNodePointer(docPtr, root);

        Element author = doc.createElement("author");
        root.appendChild(author);
        Text text = doc.createTextNode("John Doe");
        author.appendChild(text);

        DOMNodePointer authorPtr = new DOMNodePointer(rootPtr, author);
        DOMNodePointer textPtr = new DOMNodePointer(authorPtr, text);

        String path = textPtr.asPath();
        assertNotNull(path, "Path for text node should not be null");
        String lower = path.toLowerCase();
        assertTrue(lower.contains("author"), "Path should include parent element 'author': " + path);
        assertTrue(lower.contains("text"), "Path should include text node indicator: " + path);

        // Ensure idempotence
        assertEquals(path, textPtr.asPath(), "asPath should be idempotent for the same node");
    }

